class Solution {
public:
    long long findScore(std::vector<int>& nums) {
        int n = nums.size();
        std::vector<std::pair<int, int>> elements(n);
        for (int i = 0; i < n; ++i) elements[i] = {nums[i], i};
        std::sort(elements.begin(), elements.end());
        std::vector<bool> marked(n, false);
        long long score = 0;
        for (const auto& [val, i] : elements) {
            if (!marked[i]) {
                score += val;
                marked[i] = true;
                if (i > 0) marked[i - 1] = true;
                if (i + 1 < n) marked[i + 1] = true;
            }
        }
        return score;
    }
};

class Solution {
    public long findScore(int[] nums) {
        int n = nums.length;
        Integer[] indices = new Integer[n];
        for (int i = 0; i < n; i++) indices[i] = i;
        java.util.Arrays.sort(indices, (a, b) -> {
            if (nums[a] != nums[b]) return Integer.compare(nums[a], nums[b]);
            return Integer.compare(a, b);
        });
        boolean[] marked = new boolean[n];
        long score = 0;
        for (int i : indices) {
            if (!marked[i]) {
                score += nums[i];
                marked[i] = true;
                if (i > 0) marked[i - 1] = true;
                if (i + 1 < n) marked[i + 1] = true;
            }
        }
        return score;
    }
}

var findScore = function(nums) {
    const n = nums.length;
    const indices = Array.from({ length: n }, (_, i) => i);
    indices.sort((a, b) => nums[a] !== nums[b] ? nums[a] - nums[b] : a - b);
    const marked = new Uint8Array(n);
    let score = 0;
    for (const i of indices) {
        if (!marked[i]) {
            score += nums[i];
            marked[i] = 1;
            if (i > 0) marked[i - 1] = 1;
            if (i + 1 < n) marked[i + 1] = 1;
        }
    }
    return score;
};
